// Bilingual (EN + FR) HR document engine.
//
// Attestations, mission orders and invitation letters produced here are read by
// embassies, consulates and immigration services, so the wording is fixed in
// templates rather than generated by a model: the same input must always yield
// the same text, in both languages, with nothing invented. The module is
// isomorphic (no server-only imports) so the form can validate and preview
// locally before anything is issued.

// --- Field metadata ------------------------------------------------------

export type HrFieldKind = "text" | "date" | "money" | "textarea" | "select";

export interface HrSelectOption {
  value: string;
  en: string;
  fr: string;
}

export interface HrDocField {
  key: string;
  en: string;
  fr: string;
  kind: HrFieldKind;
  required: boolean;
  options?: HrSelectOption[];
  /**
   * Free text that reads as English prose. The form offers a companion
   * `<key>_fr` input so the French version is professionally equivalent rather
   * than an English fragment dropped into French sentences; when it is left
   * empty the English value is reused.
   */
  translatable?: boolean;
  /** Pre-filled when the officer opens the form. */
  default?: string;
  /** Grouping hint for the form layout. */
  group: "subject" | "details" | "issuance" | "signatory";
  /** Render the input full width. */
  wide?: boolean;
}

