function field(f: Omit<HrDocField, "group"> & { group?: HrDocField["group"] }): HrDocField {
  return { group: "details", ...f };
}

// Subject-of-the-document block, shared by every employee-based attestation.
function subjectFields(opts: { positionRequired?: boolean; startRequired?: boolean; statusRequired?: boolean } = {}): HrDocField[] {
  return [
    field({ key: "employee_title", en: "Courtesy title", fr: "Civilité", kind: "select", required: false, options: HONORIFICS, group: "subject" }),
    field({ key: "employee_full_name", en: "Full name", fr: "Nom et prénoms", kind: "text", required: true, group: "subject", wide: true }),
    field({ key: "employee_position", en: "Position held", fr: "Poste occupé", kind: "text", required: !!opts.positionRequired, group: "subject", translatable: true }),
    field({ key: "employee_department", en: "Department", fr: "Département", kind: "text", required: false, group: "subject", translatable: true }),
    field({ key: "employee_no", en: "Employee number", fr: "Matricule", kind: "text", required: false, group: "subject" }),
    field({ key: "employee_id_type", en: "Identity document", fr: "Pièce d'identité", kind: "select", required: false, options: ID_TYPES, default: "PASSPORT", group: "subject" }),
    field({ key: "employee_id_number", en: "Identity document number", fr: "Numéro de la pièce", kind: "text", required: false, group: "subject" }),
    field({ key: "employee_nationality", en: "Nationality", fr: "Nationalité", kind: "text", required: false, group: "subject", translatable: true }),
    field({ key: "employment_start_date", en: "Employment start date", fr: "Date de prise de service", kind: "date", required: !!opts.startRequired, group: "subject" }),
    field({ key: "employment_status", en: "Contract type", fr: "Type de contrat", kind: "select", required: !!opts.statusRequired, options: EMPLOYMENT_STATUSES, group: "subject" }),
  ];
}

// Issuance + signatory block, shared by every document type.
function commonFields(purposeRequired = true): HrDocField[] {
  return [
    field({ key: "addressee", en: "Addressee (optional)", fr: "Destinataire (facultatif)", kind: "text", required: false, translatable: true, group: "issuance", wide: true }),
    field({ key: "purpose", en: "Purpose of the document", fr: "Objet du document", kind: "textarea", required: purposeRequired, group: "issuance", wide: true, translatable: true }),
    field({ key: "company_address", en: "Office address", fr: "Adresse du cabinet", kind: "text", required: true, default: DEFAULT_ADDRESS, group: "issuance", wide: true }),
    field({ key: "place_of_issue", en: "Place of issue", fr: "Lieu d'établissement", kind: "text", required: true, default: DEFAULT_PLACE, group: "issuance" }),
    field({ key: "issue_date", en: "Date of issue", fr: "Date d'établissement", kind: "date", required: true, group: "issuance" }),
    field({ key: "hr_officer_name", en: "Signatory name", fr: "Nom du signataire", kind: "text", required: true, group: "signatory" }),
    field({ key: "hr_officer_title", en: "Signatory title", fr: "Qualité du signataire", kind: "text", required: true, group: "signatory", translatable: true }),
    field({ key: "hr_phone", en: "HR telephone", fr: "Téléphone RH", kind: "text", required: true, group: "signatory" }),
    field({ key: "hr_email", en: "HR email", fr: "Courriel RH", kind: "text", required: true, group: "signatory" }),
  ];
}

export type HrDocTypeKey =
  | "work_attestation"
  | "employment_confirmation"
  | "leave_attestation"
  | "mission_order"
  | "salary_attestation"
  | "internship_attestation"
  | "invitation_letter"
  | "custom";

